L1: // What an agent reads to reach an answer: `knowledge find` (and `--code`) against grep + Read.
L2: // The fixture is this repository itself, so the number is public and anyone can rerun it: its
L3: // `template/` and `docs/` (plus README.md and AGENTS.md) as the vault, a clone of its HEAD as the
L4: // checkout, both in a temp folder with their own KNOWLEDGE_HOME and HOME. Method: docs/benchmark.md.
L5: // Run from the repo root:  bun --bun bench/tokens.ts target/release/knowledge
L6: import { cpSync, mkdtempSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
L7: import { basename, join, relative, resolve } from "node:path";
L8: import { tmpdir } from "node:os";
L9: import { spawnSync } from "node:child_process";
L10: 
L11: const repo = resolve(import.meta.dir, "..");
L12: const bin = resolve(process.argv[2] ?? "target/release/knowledge");
L13: const { notes, code } = JSON.parse(readFileSync(join(import.meta.dir, "questions.json"), "utf8"));
L14: const RUNS = 5; // latency: the median of five runs per question
L15: 
L16: // --- the fixture -------------------------------------------------------------------------------
L17: const tmp = mkdtempSync(join(tmpdir(), "kb-"));
L18: const vault = join(tmp, "vault"), dev = join(tmp, "dev"), home = join(tmp, "home"), user = join(tmp, "user");
L19: const checkout = join(dev, "knowledge");
L20: cpSync(join(repo, "template"), vault, { recursive: true });
L21: const docs = join(vault, "20-Knowledge", "knowledge");
L22: mkdirSync(docs, { recursive: true });
L23: for (const f of readdirSync(join(repo, "docs")).filter((f) => f.endsWith(".md"))) cpSync(join(repo, "docs", f), join(docs, f));
L24: cpSync(join(repo, "README.md"), join(docs, "Overview.md")); // `README` is the template's own note
L25: cpSync(join(repo, "AGENTS.md"), join(docs, "Agent-Install.md"));
L26: mkdirSync(dev); mkdirSync(home); mkdirSync(user);
L27: const git = spawnSync("git", ["clone", "-q", "--no-hardlinks", repo, checkout]);
L28: if (git.status !== 0) throw new Error(`git clone: ${git.stderr}`);
L29: writeFileSync(join(home, "config.json"), JSON.stringify({ vault, devRoot: dev }));
