L31: // The binary sees only the fixture: its own KNOWLEDGE_HOME, and a HOME with nothing in it.
L32: const env: Record<string, string> = { ...process.env, KNOWLEDGE_HOME: home, HOME: user, USERPROFILE: user } as any;
L33: delete env.KNOWLEDGE_CONFIG;
