L1: // knowledge's opencode plugin (vault audit S7.5). Written to ~/.config/opencode/plugins/
L2: // by `knowledge setup --harness opencode`, which replaces any edit made here.
L3: //
L4: // It only spawns the command: each opencode hook becomes one `knowledge hook <verb> --harness
L5: // opencode` call, a canonical JSON payload on stdin and one JSON reply on stdout, and the reply is
L6: // acted on here. The binary decides everything else. The pin is the version this file was written
L7: // for: a binary of another version stands down and says so once, at session start.
L8: //
L9: // The hooks, as read from opencode 2.2.1 (the S7.0 probe and the binary itself):
L10: //   event session.created             -> session   (not for a subagent's session: it has a parentID)
L11: //   session hook "prompt"             -> prompt
L12: //   session hook "context"            -> nothing spawned: it pushes the kept context into `system`
L13: //   tool hook "execute.before"        -> pre-tool  (shell and the edit tools; a deny throws)
L14: //   tool hook "execute.after"         -> post-edit or post-bash, by tool name
L15: //   event session.compaction.started  -> capture   (pre-compact)
L16: //   event session.execution.succeeded -> capture   (stop; opencode 2.2.1 has no session.idle)
L17: //   event session.deleted             -> capture   (session end)
L18: import { spawn } from "node:child_process";
L19: import { existsSync } from "node:fs";
L20: import { homedir } from "node:os";
L21: import { delimiter, join } from "node:path";
L22: 
L23: const PIN = "0.13.2";
L24: // opencode's service is started by the login manager (systemd --user on Arch), whose PATH lacks
L25: // ~/.cargo/bin, where `cargo install` puts the binary: a bare "knowledge" was ENOENT, and every hook
L26: // came back empty (Arch, 2026-11-25). So PATH first, as the other harnesses run it, then cargo's bin.
L27: const EXE = process.platform === "win32" ? "knowledge.exe" : "knowledge";
L28: const BIN =
L29:   [...(process.env.PATH ?? "").split(delimiter), join(process.env.CARGO_HOME ?? join(homedir(), ".cargo"), "bin")]
L30:     .filter(Boolean)
L31:     .map((dir) => join(dir, EXE))
L32:     .find((p) => existsSync(p)) ?? "knowledge";
L33: const EDITS = new Set(["edit", "write", "patch"]);
L34: 
L35: type Reply = { context?: string; decision?: string; reason?: string };
L36: 
L37: // One hook call. Fails silent: a missing binary, a timeout or bad output is an empty reply, so a
L38: // broken install never blocks opencode (the guard allows, as the binary's own guard does).
L39: function knowledge(verb: string, payload: object, ms: number): Promise<Reply> {
L40:   return new Promise((done) => {
L41:     let out = "";
L42:     let child: ReturnType<typeof spawn>;
L43:     try {
L44:       child = spawn(BIN, ["hook", verb, "--harness", "opencode", "--pin", PIN], {
L45:         stdio: ["pipe", "pipe", "ignore"],
L46:         windowsHide: true,
L47:       });
L48:     } catch {
L49:       return done({});
L50:     }
L51:     const timer = setTimeout(() => child.kill(), ms);
L52:     child.stdout?.on("data", (b) => (out += b));
L53:     child.on("error", () => {
L54:       clearTimeout(timer);
L55:       done({});
L56:     });
L57:     child.on("close", () => {
L58:       clearTimeout(timer);
L59:       try {
L60:         done(out.trim() ? JSON.parse(out) : {});
L61:       } catch {
L62:         done({});
L63:       }
L64:     });
L65:     child.stdin?.on("error", () => {});
L66:     child.stdin?.end(JSON.stringify(payload));
L67:   });
L68: }
